INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7132374, 1092483, 37858, '<td valign="top">Love the title.  So appropriate.</td>', 'Love the title.  So appropriate.', '2013-11-20 00:23:29.000000', NULL, 1),
(7132376, 1092810, 141247, '<td valign="top">Very nice. if possible plz write about the lighting setup.</td>', 'Very nice. if possible plz write about the lighting setup.', '2013-11-20 00:23:56.000000', NULL, 1),
(7132380, 1092730, 141247, '<td valign="top">Looking very nice, the bottle top wrapper is not fixed properly, it''s looking odd... 8</td>', 'Looking very nice, the bottle top wrapper is not fixed properly, it''s looking odd... 8', '2013-11-20 00:29:04.000000', NULL, 1),
(7132418, 1092756, 58667, '<td valign="top">I love how I want to know more about the BG, and then the glass ball shows me.</td>', 'I love how I want to know more about the BG, and then the glass ball shows me.', '2013-11-20 02:01:02.000000', NULL, 1),
(7132419, 1092574, 58667, '<td valign="top">The way I see this photo:<br/>1. Drinking dark rum neat isn''t all that common - maybe a nice whiskey would have been more appropriate<br/>2. The colour of the liquid in the glass doesn''t look like rum (a bit red) - not saying it isn''t rum though<br/>3. The angle is a bit high (for my personal preference)<br/>4. I love the negative space<br/>5. I like how much reflection was added - the bottom of the glass isn''t to near the bottom of the frame, nor is it to far</td>', 'The way I see this photo:1. Drinking dark rum neat isn''t all that common - maybe a nice whiskey would have been more appropriate2. The colour of the liquid in the glass doesn''t look like rum (a bit red) - not saying it isn''t rum though3. The angle is a bit high (for my personal preference)4. I love the negative space5. I like how much reflection was added - the bottom of the glass isn''t to near the bottom of the frame, nor is it to far', '2013-11-20 02:05:23.000000', NULL, 1),
(7132420, 1092716, 58667, '<td valign="top">For me, with a photo like this, I need to see some sort of story. The blue light doesn''t look natural (if there was some background context like bar lights or something then the blue light might have made sense).</td>', 'For me, with a photo like this, I need to see some sort of story. The blue light doesn''t look natural (if there was some background context like bar lights or something then the blue light might have made sense).', '2013-11-20 02:07:11.000000', NULL, 1),
(7132421, 1092713, 58667, '<td valign="top">An interesting subject. It looks like this is inside an old tool shed or workshop on a high shelf in a dark corner, but then the reflections lead me to believe otherwise. I personally would have liked to see more of the thing on the right (brighter). Also, perhaps the focus could have been on the bulbs in the foreground? Maybe you did try that and it didn''t look as good.</td>', 'An interesting subject. It looks like this is inside an old tool shed or workshop on a high shelf in a dark corner, but then the reflections lead me to believe otherwise. I personally would have liked to see more of the thing on the right (brighter). Also, perhaps the focus could have been on the bulbs in the foreground? Maybe you did try that and it didn''t look as good.', '2013-11-20 02:11:16.000000', NULL, 1),
(7132422, 1092772, 58667, '<td valign="top">This is a pleasant composition. The sharpening works well on the subject, but it really spoils the bokeh. I love the colours.</td>', 'This is a pleasant composition. The sharpening works well on the subject, but it really spoils the bokeh. I love the colours.', '2013-11-20 02:13:21.000000', NULL, 1),
(7132423, 1092834, 58667, '<td valign="top">Very busy, but that works here. I like the hardness of the glass and the softness of the flower. This must have been challenging. I think the fact that it isn''t centered makes it better.</td>', 'Very busy, but that works here. I like the hardness of the glass and the softness of the flower. This must have been challenging. I think the fact that it isn''t centered makes it better.', '2013-11-20 02:15:27.000000', NULL, 1),
(7132424, 1092765, 58667, '<td valign="top">The only thing that makes me possibly believe there is glass in this photo is the title.</td>', 'The only thing that makes me possibly believe there is glass in this photo is the title.', '2013-11-20 02:17:42.000000', NULL, 1),
(7132425, 1092231, 58667, '<td valign="top">Without the person there this could have (for me) been better. I like the scenery - beautiful colours.</td>', 'Without the person there this could have (for me) been better. I like the scenery - beautiful colours.', '2013-11-20 02:19:44.000000', NULL, 1),
(7132427, 1092823, 58667, '<td valign="top">I personally don''t like this overdone out of focus type of processing. I also don''t quite get the point of this photo.</td>', 'I personally don''t like this overdone out of focus type of processing. I also don''t quite get the point of this photo.', '2013-11-20 02:21:43.000000', NULL, 1),
(7132428, 1092596, 58667, '<td valign="top">I would never guess this is glass. Interesting abstract.</td>', 'I would never guess this is glass. Interesting abstract.', '2013-11-20 02:22:21.000000', NULL, 1),
(7132431, 1092252, 58667, '<td valign="top">Interesting lines. Hectic colour! Sharper focus could maybe have helped a bit. It also feels a bit tilted? I also feel it''s a bit bright</td>', 'Interesting lines. Hectic colour! Sharper focus could maybe have helped a bit. It also feels a bit tilted? I also feel it''s a bit bright', '2013-11-20 02:30:46.000000', NULL, 1),
(7132432, 1092836, 58667, '<td valign="top">Interesting, nice colours, nice lighting. I believe this should do well.</td>', 'Interesting, nice colours, nice lighting. I believe this should do well.', '2013-11-20 02:31:18.000000', NULL, 1),
(7132433, 1092764, 58667, '<td valign="top">Slightly strange angle and crop, but I like the focus. The background also works well.</td>', 'Slightly strange angle and crop, but I like the focus. The background also works well.', '2013-11-20 02:32:26.000000', NULL, 1),
(7132435, 1092832, 58667, '<td valign="top">Way too overdone in my opinion. Also it''s not clear where the glass is (if there is any).</td>', 'Way too overdone in my opinion. Also it''s not clear where the glass is (if there is any).', '2013-11-20 02:33:26.000000', NULL, 1),
(7132437, 1092791, 58667, '<td valign="top">Nice arrangement. There seems to be heavy tilt. Maybe the DOF could have been much more? I like the colours.</td>', 'Nice arrangement. There seems to be heavy tilt. Maybe the DOF could have been much more? I like the colours.', '2013-11-20 02:36:01.000000', NULL, 1),
(7132438, 1092655, 58667, '<td valign="top">This is a nice gentle shot with a welcoming feel.</td>', 'This is a nice gentle shot with a welcoming feel.', '2013-11-20 02:37:06.000000', NULL, 1),
(7132442, 1092550, 58667, '<td valign="top">Interesting. My critique: the eye being so close to the edge of the glass is causing a bit of blur (could also be the angle of the magnifying glass). There''s something behind the model which is off putting. The black and white is very black and white. It also looks like the focus behind the glass was blurred and actually not out of focus.</td>', 'Interesting. My critique: the eye being so close to the edge of the glass is causing a bit of blur (could also be the angle of the magnifying glass). There''s something behind the model which is off putting. The black and white is very black and white. It also looks like the focus behind the glass was blurred and actually not out of focus.', '2013-11-20 02:43:25.000000', NULL, 1),
(7132444, 1092569, 58667, '<td valign="top">This is very nice! Great colours and focus. I also like the angle. The only thing taking a point away for me is the distracting foreground blurry thing on the right. In a way it adds to the photo, but then it does distract a bit too much. I also wonder if this really is glass? ;)</td>', 'This is very nice! Great colours and focus. I also like the angle. The only thing taking a point away for me is the distracting foreground blurry thing on the right. In a way it adds to the photo, but then it does distract a bit too much. I also wonder if this really is glass? ;)', '2013-11-20 02:46:01.000000', NULL, 1),
(7132445, 1092788, 58667, '<td valign="top">This is a proper DPC top 10. The one thing to make me minus a point is the tilt (although it''s not so bad).</td>', 'This is a proper DPC top 10. The one thing to make me minus a point is the tilt (although it''s not so bad).', '2013-11-20 02:47:45.000000', NULL, 1),
(7132446, 1092256, 58667, '<td valign="top">Glass? Subject? Story?</td>', 'Glass? Subject? Story?', '2013-11-20 02:48:24.000000', NULL, 1),
(7132448, 1092732, 58667, '<td valign="top">Looks delicious! I can''t minus any points here (not even for that harsh reflection on the left of the glass).</td>', 'Looks delicious! I can''t minus any points here (not even for that harsh reflection on the left of the glass).', '2013-11-20 02:50:02.000000', NULL, 1),
(7132544, 1092824, 129147, '<td valign="top">Like the colors, not sure that I care for the vignette, or tilt.</td>', 'Like the colors, not sure that I care for the vignette, or tilt.', '2013-11-20 07:41:35.000000', NULL, 1),
(7132552, 1092550, 49954, '<td valign="top">Yes there is glass in the picture, but it''s not really a photo OF glass but more like shooting THROUGH glass... which technically every photo in this challenge did.</td>', 'Yes there is glass in the picture, but it''s not really a photo OF glass but more like shooting THROUGH glass... which technically every photo in this challenge did.', '2013-11-20 08:00:23.000000', NULL, 1),
(7132554, 1092828, 49954, '<td valign="top">"Thou shalt not make unto thee any graven image, or any likeness of any thing that is in heaven above, or that is in the earth beneath, or that is in the water under the earth:" ~ Exodus 20:4</td>', '"Thou shalt not make unto thee any graven image, or any likeness of any thing that is in heaven above, or that is in the earth beneath, or that is in the water under the earth:" ~ Exodus 20:4', '2013-11-20 08:02:01.000000', NULL, 1),
(7132568, 1092823, 21304, '<td valign="top">this one takes a few moments to catch, but once you do, it''s brilliant (no vote, at least for the moment)</td>', 'this one takes a few moments to catch, but once you do, it''s brilliant (no vote, at least for the moment)', '2013-11-20 09:05:51.000000', NULL, 1),
(7132582, 1092703, 129147, '<td valign="top">Really held my attention, and enjoyed the lines!</td>', 'Really held my attention, and enjoyed the lines!', '2013-11-20 09:30:29.000000', NULL, 1),
(7132583, 1092311, 129147, '<td valign="top">One of the best! Lots to look at!</td>', 'One of the best! Lots to look at!', '2013-11-20 09:31:05.000000', NULL, 1),
(7132584, 1092647, 129147, '<td valign="top">Really enjoyed this image.</td>', 'Really enjoyed this image.', '2013-11-20 09:31:34.000000', NULL, 1),
(7132585, 1091975, 129147, '<td valign="top">Like the color here, and it held my eye.</td>', 'Like the color here, and it held my eye.', '2013-11-20 09:31:53.000000', NULL, 1),
(7132586, 1092784, 129147, '<td valign="top">Simple and effective.</td>', 'Simple and effective.', '2013-11-20 09:32:11.000000', NULL, 1),
(7132587, 1092483, 129147, '<td valign="top">I liked the creativity here.</td>', 'I liked the creativity here.', '2013-11-20 09:32:28.000000', NULL, 1),
(7132588, 1092651, 129147, '<td valign="top">Enjoy the colors.</td>', 'Enjoy the colors.', '2013-11-20 09:33:44.000000', NULL, 1),
(7132589, 1092553, 129147, '<td valign="top">Colors seem a bit flat.</td>', 'Colors seem a bit flat.', '2013-11-20 09:34:14.000000', NULL, 1),
(7132592, 1092810, 129147, '<td valign="top">Nicely done, I like the lighting a lot.</td>', 'Nicely done, I like the lighting a lot.', '2013-11-20 09:35:31.000000', NULL, 1),
(7132593, 1092614, 129147, '<td valign="top">Really held my attention!!! I hope this does well.</td>', 'Really held my attention!!! I hope this does well.', '2013-11-20 09:35:56.000000', NULL, 1),
(7132594, 1092651, 58667, '<td valign="top">Nice art photo. The colours mix well and show off the glass well. I like the composition - it''s also interesting. I feel like that saucer is standing like that so unnaturally! :D But this looks good and is unique.</td>', 'Nice art photo. The colours mix well and show off the glass well. I like the composition - it''s also interesting. I feel like that saucer is standing like that so unnaturally! :D But this looks good and is unique.', '2013-11-20 09:36:09.000000', NULL, 1),
(7132596, 1092716, 129147, '<td valign="top">Great lighting!</td>', 'Great lighting!', '2013-11-20 09:37:04.000000', NULL, 1),
(7132597, 1092730, 129147, '<td valign="top">Clever!</td>', 'Clever!', '2013-11-20 09:37:51.000000', NULL, 1),
(7132598, 1092612, 58667, '<td valign="top">What a mess! :D This is quite a spectacular break. How many takes did you do? If the liquid was more transparent I would probably be able to see more of the breakage, but still, well done.</td>', 'What a mess! :D This is quite a spectacular break. How many takes did you do? If the liquid was more transparent I would probably be able to see more of the breakage, but still, well done.', '2013-11-20 09:38:31.000000', NULL, 1),
(7132599, 1092654, 129147, '<td valign="top">I thought that this was interesting that you went vertical.</td>', 'I thought that this was interesting that you went vertical.', '2013-11-20 09:38:41.000000', NULL, 1),
(7132600, 1092784, 58667, '<td valign="top">Not very unique, but technically it''s still a good photo.</td>', 'Not very unique, but technically it''s still a good photo.', '2013-11-20 09:39:42.000000', NULL, 1),
(7132601, 1092231, 129147, '<td valign="top">Wish that the man was looking out the window and not out of frame.</td>', 'Wish that the man was looking out the window and not out of frame.', '2013-11-20 09:40:14.000000', NULL, 1),
(7132602, 1092795, 58667, '<td valign="top">To me this isn''t very pretty and I don''t know what it is. Interesting focus though.</td>', 'To me this isn''t very pretty and I don''t know what it is. Interesting focus though.', '2013-11-20 09:40:22.000000', NULL, 1),
(7132603, 1092814, 129147, '<td valign="top">Pretty cool and outside the box!</td>', 'Pretty cool and outside the box!', '2013-11-20 09:41:30.000000', NULL, 1),
(7132604, 1092723, 58667, '<td valign="top">I like the background. I don''t like the lack of context - for this sort of photo I look for some sort of context to give a bit of a story. This to me is a snapshot of a lampshade which isn''t all that sharp and also isn''t interestingly lit.</td>', 'I like the background. I don''t like the lack of context - for this sort of photo I look for some sort of context to give a bit of a story. This to me is a snapshot of a lampshade which isn''t all that sharp and also isn''t interestingly lit.', '2013-11-20 09:42:58.000000', NULL, 1),
(7132605, 1092540, 129147, '<td valign="top">Like the framing of this!</td>', 'Like the framing of this!', '2013-11-20 09:43:10.000000', NULL, 1),
(7132607, 1092816, 58667, '<td valign="top">Wow busy! That glass in the middle is excellent!</td>', 'Wow busy! That glass in the middle is excellent!', '2013-11-20 09:43:46.000000', NULL, 1),
(7132609, 1092570, 58667, '<td valign="top">Interesting reflections, nice lighting, not the most interesting photo (but I''m not a huge fan of pointless still life). The only critique I have is that the book could be the other way around. Now it''s upside down.</td>', 'Interesting reflections, nice lighting, not the most interesting photo (but I''m not a huge fan of pointless still life). The only critique I have is that the book could be the other way around. Now it''s upside down.', '2013-11-20 09:47:49.000000', NULL, 1),
(7132639, 1092737, 108580, '<td valign="top">Rich and subdued. Beautiful.</td>', 'Rich and subdued. Beautiful.', '2013-11-20 11:32:29.000000', NULL, 1),
(7132641, 1092548, 108580, '<td valign="top">Superior lighting. WD.</td>', 'Superior lighting. WD.', '2013-11-20 11:33:04.000000', NULL, 1),
(7132645, 1092810, 108580, '<td valign="top">Perfection in lighting and symmetry. An obvious entry naturally and that''s what does well, but it''s no accident to do it this well.<br/>(Team #1 TPL2 Image, sadly no vote. 8-10 depending on final votes and bumps.)</td>', 'Perfection in lighting and symmetry. An obvious entry naturally and that''s what does well, but it''s no accident to do it this well.(Team #1 TPL2 Image, sadly no vote. 8-10 depending on final votes and bumps.)', '2013-11-20 11:37:27.000000', NULL, 1),
(7132646, 1092732, 108580, '<td valign="top">Lovely tones and DOF. Dark chocolate and complimentary lighting. Very nice.</td>', 'Lovely tones and DOF. Dark chocolate and complimentary lighting. Very nice.', '2013-11-20 11:40:40.000000', NULL, 1),
(7132647, 1092672, 108580, '<td valign="top">Crisp and perfect exposure in B&amp;W. Half the stem and foot awol and the wide open space at top feels like there''s something missing. Volume. Completeness. Others would vote that to a 4 or 3. Not me. There''s enough here to enjoy, barring those small niggles. 6</td>', 'Crisp and perfect exposure in B&W. Half the stem and foot awol and the wide open space at top feels like there''s something missing. Volume. Completeness. Others would vote that to a 4 or 3. Not me. There''s enough here to enjoy, barring those small niggles. 6', '2013-11-20 11:43:29.000000', NULL, 1),
(7132648, 1092462, 108580, '<td valign="top">Very artistic and appealing. Unique too even though it has a Wine Magazine Wow to it. Well done. That''s photography.</td>', 'Very artistic and appealing. Unique too even though it has a Wine Magazine Wow to it. Well done. That''s photography.', '2013-11-20 11:45:47.000000', NULL, 1),
(7132649, 1092717, 108580, '<td valign="top">An excellent well lit colourful display of the barman''s office. Some things everyone has seen but never had the chance to actually admire! There''s a wee bit of money lined up there sonny. DMC Richard and I hope this goes to 6 at least. (Team #1 TPL2 Image so sadly no vote, 7 if I could)</td>', 'An excellent well lit colourful display of the barman''s office. Some things everyone has seen but never had the chance to actually admire! There''s a wee bit of money lined up there sonny. DMC Richard and I hope this goes to 6 at least. (Team #1 TPL2 Image so sadly no vote, 7 if I could)', '2013-11-20 11:49:54.000000', NULL, 1),
(7132662, 1092654, 170570, '<td valign="top">this picture is very dull and awesome ;)</td>', 'this picture is very dull and awesome ;)', '2013-11-20 12:26:39.000000', NULL, 1),
(7132716, 1092574, 108580, '<td valign="top">Nice and subdued lighting, crisp and I can almost smell the vanilla. Missing coke and ice though! Baie mooi!</td>', 'Nice and subdued lighting, crisp and I can almost smell the vanilla. Missing coke and ice though! Baie mooi!', '2013-11-20 14:07:26.000000', NULL, 1),
(7132745, 1091916, 108580, '<td valign="top">No visible glass but the implication is a solid enough reference to know. 7.</td>', 'No visible glass but the implication is a solid enough reference to know. 7.', '2013-11-20 15:44:59.000000', NULL, 1),
