(7134549, 1092548, 58667, '<td valign="top">The colours are nice and original. I think you were going for the very low light, but for me if the contrast was a bit less it may have been a bit better. Still - a good image.</td>', 'The colours are nice and original. I think you were going for the very low light, but for me if the contrast was a bit less it may have been a bit better. Still - a good image.', '2013-11-25 01:34:23.000000', NULL, 1),
(7134550, 1092810, 58667, '<td valign="top">Not just monotone - nice! And a very interesting table shot.</td>', 'Not just monotone - nice! And a very interesting table shot.', '2013-11-25 01:35:03.000000', NULL, 1),
(7134551, 1092742, 58667, '<td valign="top">A nice abstract, but I just don''t see the glass...</td>', 'A nice abstract, but I just don''t see the glass...', '2013-11-25 01:36:14.000000', NULL, 1),
(7134552, 1092640, 58667, '<td valign="top">Pretty. And the soft focus works well on this.</td>', 'Pretty. And the soft focus works well on this.', '2013-11-25 01:36:53.000000', NULL, 1),
(7134553, 1092329, 58667, '<td valign="top">Nice! Great colours!</td>', 'Nice! Great colours!', '2013-11-25 01:37:17.000000', NULL, 1),
(7134554, 1092563, 58667, '<td valign="top">Exactly! Why?! Maybe slightly more context would have worked a bit better?</td>', 'Exactly! Why?! Maybe slightly more context would have worked a bit better?', '2013-11-25 01:38:12.000000', NULL, 1),
(7134555, 1092653, 58667, '<td valign="top">Nicely done. This shape of glasses has become so popular. :)</td>', 'Nicely done. This shape of glasses has become so popular. :)', '2013-11-25 01:38:52.000000', NULL, 1),
(7134556, 1092828, 58667, '<td valign="top">It is existing art as is, so if this were to be a photo showcasing the piece, then perfect. And the colours and lighting are also perfect as they are. Very much how I''d expect to see this if I saw it in real life.</td>', 'It is existing art as is, so if this were to be a photo showcasing the piece, then perfect. And the colours and lighting are also perfect as they are. Very much how I''d expect to see this if I saw it in real life.', '2013-11-25 01:40:55.000000', NULL, 1),
(7134557, 1092316, 58667, '<td valign="top">Interesting shot and good architecture!</td>', 'Interesting shot and good architecture!', '2013-11-25 01:43:38.000000', NULL, 1),
(7134560, 1092642, 103032, '<td valign="top">Just curious why you choose portrait orientation vs landscape orientation.  In any case I like the impressionist feel to this.  B&amp;W seems fitting for the rain.</td>', 'Just curious why you choose portrait orientation vs landscape orientation.  In any case I like the impressionist feel to this.  B&W seems fitting for the rain.', '2013-11-25 01:55:17.000000', NULL, 1),
(7134572, 1092826, 58667, '<td valign="top">Wow reflections!</td>', 'Wow reflections!', '2013-11-25 03:17:57.000000', NULL, 1),
(7134573, 1092786, 58667, '<td valign="top">For glass, the soft focus is probably not the best idea, but it''s original. The liquid level isn''t quite the same in the glasses nor is it deliberately different (or at least doesn''t look so).</td>', 'For glass, the soft focus is probably not the best idea, but it''s original. The liquid level isn''t quite the same in the glasses nor is it deliberately different (or at least doesn''t look so).', '2013-11-25 03:19:06.000000', NULL, 1),
(7134574, 1092597, 58667, '<td valign="top">Nice! Not very easy...</td>', 'Nice! Not very easy...', '2013-11-25 03:19:32.000000', NULL, 1),
(7134575, 1092608, 58667, '<td valign="top">I was waiting for a science shot. And it''s a good one too!</td>', 'I was waiting for a science shot. And it''s a good one too!', '2013-11-25 03:19:53.000000', NULL, 1),
(7134577, 1092741, 58667, '<td valign="top">Very nice. I like the interestingness happening there in the middle lit pane.</td>', 'Very nice. I like the interestingness happening there in the middle lit pane.', '2013-11-25 03:22:02.000000', NULL, 1),
(7134578, 1092807, 58667, '<td valign="top">Lovely background.</td>', 'Lovely background.', '2013-11-25 03:22:22.000000', NULL, 1),
(7134579, 1092063, 58667, '<td valign="top">Sad. For me the frame isn''t lit enough.</td>', 'Sad. For me the frame isn''t lit enough.', '2013-11-25 03:23:48.000000', NULL, 1),
(7134580, 1092837, 58667, '<td valign="top">Nice. I like the grainy texture.</td>', 'Nice. I like the grainy texture.', '2013-11-25 03:24:08.000000', NULL, 1),
(7134581, 1092757, 58667, '<td valign="top">Well captured!</td>', 'Well captured!', '2013-11-25 03:24:56.000000', NULL, 1),
(7134582, 1091897, 58667, '<td valign="top">I like the reflections here - really bring out the glass.</td>', 'I like the reflections here - really bring out the glass.', '2013-11-25 03:25:23.000000', NULL, 1),
(7134583, 1092743, 58667, '<td valign="top">The sky is very well captured. I think this is the best architecture photo in the challenge.</td>', 'The sky is very well captured. I think this is the best architecture photo in the challenge.', '2013-11-25 03:25:59.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7134584, 1092540, 58667, '<td valign="top">Excellent photo!</td>', 'Excellent photo!', '2013-11-25 03:28:42.000000', NULL, 1),
(7134592, 1092814, 58667, '<td valign="top">Nice macro. :) I think the focus could possibly be a bit better? Not an easy shot. What is this?</td>', 'Nice macro. :) I think the focus could possibly be a bit better? Not an easy shot. What is this?', '2013-11-25 03:43:27.000000', NULL, 1),
(7134616, 1092830, 108580, '<td valign="top">Rather clever entry. WD.</td>', 'Rather clever entry. WD.', '2013-11-25 06:44:29.000000', NULL, 1),
(7134631, 1092536, 58667, '<td valign="top">Nice strong lines and contrast.</td>', 'Nice strong lines and contrast.', '2013-11-25 08:52:15.000000', NULL, 1),
(7134632, 1092835, 58667, '<td valign="top">I like the view point.</td>', 'I like the view point.', '2013-11-25 08:52:34.000000', NULL, 1),
(7134633, 1092808, 58667, '<td valign="top">I must say the colours are strange to me. Maybe I just don''t know this colour beer. :)</td>', 'I must say the colours are strange to me. Maybe I just don''t know this colour beer. :)', '2013-11-25 08:53:14.000000', NULL, 1),
(7134635, 1092648, 58667, '<td valign="top">I like the photobomb.</td>', 'I like the photobomb.', '2013-11-25 08:53:48.000000', NULL, 1),
(7134636, 1092798, 58667, '<td valign="top">This is a nice style and the soft focus strangely works well. I think it''s because of the background which is made more interesting by the refractions. The only change I can think would work well is if there was some cognac or something in the glass.</td>', 'This is a nice style and the soft focus strangely works well. I think it''s because of the background which is made more interesting by the refractions. The only change I can think would work well is if there was some cognac or something in the glass.', '2013-11-25 08:55:31.000000', NULL, 1),
(7134637, 1092727, 58667, '<td valign="top">Nice. It just looks a bit soft and over sharpened to me.</td>', 'Nice. It just looks a bit soft and over sharpened to me.', '2013-11-25 08:56:12.000000', NULL, 1),
(7134638, 1092307, 58667, '<td valign="top">This is pretty. And the cold feel is great.</td>', 'This is pretty. And the cold feel is great.', '2013-11-25 08:57:00.000000', NULL, 1),
(7134639, 1092547, 58667, '<td valign="top">For my personal taste, this doesn''t tell me anything. And there is a lot of noise for a shot where a tripod could possibly have been used to lower the ISO and the focus isn''t as sharp as one would expect.</td>', 'For my personal taste, this doesn''t tell me anything. And there is a lot of noise for a shot where a tripod could possibly have been used to lower the ISO and the focus isn''t as sharp as one would expect.', '2013-11-25 08:59:01.000000', NULL, 1),
(7134640, 1091975, 58667, '<td valign="top">Glass. Glass everywhere. :)</td>', 'Glass. Glass everywhere. :)', '2013-11-25 08:59:40.000000', NULL, 1),
(7134642, 1092824, 58667, '<td valign="top">Very nice isolation of the colours. And this is nice and sharp!</td>', 'Very nice isolation of the colours. And this is nice and sharp!', '2013-11-25 09:02:14.000000', NULL, 1),
(7134643, 1092690, 58667, '<td valign="top">For me, this is a tight crop and it''s a bit too low-key. But that''s my personal taste. The plant out there adds a nice feature.</td>', 'For me, this is a tight crop and it''s a bit too low-key. But that''s my personal taste. The plant out there adds a nice feature.', '2013-11-25 09:04:02.000000', NULL, 1),
(7134644, 1091988, 58667, '<td valign="top">This is a beautiful building. The sky looks a little unnatural to me, but I love the time of day this was taken (or at least what time it looks like).</td>', 'This is a beautiful building. The sky looks a little unnatural to me, but I love the time of day this was taken (or at least what time it looks like).', '2013-11-25 09:04:59.000000', NULL, 1),
(7134645, 1092669, 58667, '<td valign="top">Nice strong colours and I like the fact that there are no outside colours interfering as well as no external reflections interfering. For that I''ll score this up one.</td>', 'Nice strong colours and I like the fact that there are no outside colours interfering as well as no external reflections interfering. For that I''ll score this up one.', '2013-11-25 09:06:20.000000', NULL, 1),
(7134646, 1092755, 58667, '<td valign="top">I like the arrangement of the bottles.The horizon is also at a nice interesting height.</td>', 'I like the arrangement of the bottles.The horizon is also at a nice interesting height.', '2013-11-25 09:06:56.000000', NULL, 1),
(7134647, 1092151, 58667, '<td valign="top">I must be honest and say that I must vote this down because it isn''t glass. As a photo, I would like to see what this looks like with the lighting from the top right and not the bottom left to enhance the expression on the face of the model. Also, the door in the background is a bit distracting.</td>', 'I must be honest and say that I must vote this down because it isn''t glass. As a photo, I would like to see what this looks like with the lighting from the top right and not the bottom left to enhance the expression on the face of the model. Also, the door in the background is a bit distracting.', '2013-11-25 09:09:19.000000', NULL, 1),
(7134648, 1092720, 58667, '<td valign="top">I may be missing something, but I don''t really get this photo?</td>', 'I may be missing something, but I don''t really get this photo?', '2013-11-25 09:10:01.000000', NULL, 1),
(7134649, 1092737, 58667, '<td valign="top">This is good and the colours match well.</td>', 'This is good and the colours match well.', '2013-11-25 09:10:52.000000', NULL, 1),
(7134650, 1092650, 58667, '<td valign="top">Nice choice of the order of the colours. Each comes out strong.</td>', 'Nice choice of the order of the colours. Each comes out strong.', '2013-11-25 09:12:23.000000', NULL, 1),
(7134651, 1092647, 58667, '<td valign="top">I love the uniqueness of this and the framing is excellent.</td>', 'I love the uniqueness of this and the framing is excellent.', '2013-11-25 09:13:02.000000', NULL, 1),
(7134652, 1092783, 58667, '<td valign="top">This looks ominous to me. Nice sky!</td>', 'This looks ominous to me. Nice sky!', '2013-11-25 09:13:30.000000', NULL, 1),
(7134653, 1092642, 58667, '<td valign="top">Yes. :) This depicts how visibility is obscured when it rains well. This has an interestingness to it.</td>', 'Yes. :) This depicts how visibility is obscured when it rains well. This has an interestingness to it.', '2013-11-25 09:14:36.000000', NULL, 1),
(7134654, 1092462, 58667, '<td valign="top">This is very bright even on my dim monitor. But the colour is used well.</td>', 'This is very bright even on my dim monitor. But the colour is used well.', '2013-11-25 09:15:35.000000', NULL, 1),
(7134655, 1092630, 58667, '<td valign="top">For me, a strange background which doesn''t bring out the glass in the foreground. But at least it''s not the same as all the others like it.</td>', 'For me, a strange background which doesn''t bring out the glass in the foreground. But at least it''s not the same as all the others like it.', '2013-11-25 09:16:45.000000', NULL, 1),
(7134656, 1092338, 58667, '<td valign="top">I love these things. What are they called?The foreground here is great!</td>', 'I love these things. What are they called?The foreground here is great!', '2013-11-25 09:17:15.000000', NULL, 1),
(7134657, 1092380, 58667, '<td valign="top">Yes. That''s glass. :) For me there isn''t much context (the refractions could maybe have added some more - but I''m not sure that''s easy to do).</td>', 'Yes. That''s glass. :) For me there isn''t much context (the refractions could maybe have added some more - but I''m not sure that''s easy to do).', '2013-11-25 09:18:29.000000', NULL, 1),
(7134659, 1092833, 58667, '<td valign="top">This looks heavy. For me the crop is a bit too much on the right and the reflections of the umbrellas give away the studio. But the lighting is very nice on the model. And I like the tint on the model''s shoulder.</td>', 'This looks heavy. For me the crop is a bit too much on the right and the reflections of the umbrellas give away the studio. But the lighting is very nice on the model. And I like the tint on the model''s shoulder.', '2013-11-25 09:20:09.000000', NULL, 1),
(7134660, 1092729, 58667, '<td valign="top">The glass is very dark - almost looks like it isn''t glass. This is nice and sharp and the background isn''t just a plain wall, so that''s nice.</td>', 'The glass is very dark - almost looks like it isn''t glass. This is nice and sharp and the background isn''t just a plain wall, so that''s nice.', '2013-11-25 09:21:31.000000', NULL, 1),
(7134662, 1092801, 58667, '<td valign="top">The lighting is good here.</td>', 'The lighting is good here.', '2013-11-25 09:22:11.000000', NULL, 1),
(7134663, 1092672, 58667, '<td valign="top">The effect here is good. The background is very interesting and makes the glass stand out well.</td>', 'The effect here is good. The background is very interesting and makes the glass stand out well.', '2013-11-25 09:22:52.000000', NULL, 1),
(7134664, 1092830, 58667, '<td valign="top">This is well done.</td>', 'This is well done.', '2013-11-25 09:23:38.000000', NULL, 1),
(7134665, 1092656, 58667, '<td valign="top">Aah shame. But it''s an iPhone, so no biggy... ;)</td>', 'Aah shame. But it''s an iPhone, so no biggy... ;)', '2013-11-25 09:24:15.000000', NULL, 1),
(7134666, 1092717, 58667, '<td valign="top">Oh yes. I''ll have one. :)On a glass shelf too! I love the way the frame is filled. Nice.</td>', 'Oh yes. I''ll have one. :)On a glass shelf too! I love the way the frame is filled. Nice.', '2013-11-25 09:24:56.000000', NULL, 1),
(7134669, 1092275, 58667, '<td valign="top">Can''t not say this title in Ali Campbell''s voice. :) Is that texture natural?</td>', 'Can''t not say this title in Ali Campbell''s voice. :) Is that texture natural?', '2013-11-25 09:30:00.000000', NULL, 1),
(7134670, 1092621, 58667, '<td valign="top">Nice take on the glass table shot style.</td>', 'Nice take on the glass table shot style.', '2013-11-25 09:30:42.000000', NULL, 1),
(7134671, 1092482, 58667, '<td valign="top">Well done with that refraction.</td>', 'Well done with that refraction.', '2013-11-25 09:31:08.000000', NULL, 1),
(7134672, 1092703, 58667, '<td valign="top">Nice strong lines of light. I like this macro of a prism. Very well captured.</td>', 'Nice strong lines of light. I like this macro of a prism. Very well captured.', '2013-11-25 09:31:53.000000', NULL, 1),
(7134673, 1092654, 58667, '<td valign="top">Interesting that it''s vertical. Maybe tilted more counter-clockwise could also have been tried?</td>', 'Interesting that it''s vertical. Maybe tilted more counter-clockwise could also have been tried?', '2013-11-25 09:32:39.000000', NULL, 1),
(7134674, 1092554, 58667, '<td valign="top">The background for me a bit too bright. But the colours in the tubes is well done!</td>', 'The background for me a bit too bright. But the colours in the tubes is well done!', '2013-11-25 09:33:19.000000', NULL, 1),
(7134678, 1092311, 58667, '<td valign="top">This is one of those very beautiful and tranquil photos. Looked at this one for longer than any other just because it''s nice to look at. Isn''t that what it''s about?<br/> <br/>I''m back to bump this one up more.</td>', 'This is one of those very beautiful and tranquil photos. Looked at this one for longer than any other just because it''s nice to look at. Isn''t that what it''s about? I''m back to bump this one up more.', '2013-11-25 09:46:11.000000', NULL, 1),
(7134744, 1092788, 100773, '<td valign="top">I would have worked more with high lights and shadows here, two curves layers, one in screen blending mode and one in multiply, then invert the masks and brush out high lights in screen and shadows in multiply. 10% opacity brush is usually good. And also darkened the background, and maybe used a subtle vignette. But that''s what I would''ve done. Nice shot though! 8</td>', 'I would have worked more with high lights and shadows here, two curves layers, one in screen blending mode and one in multiply, then invert the masks and brush out high lights in screen and shadows in multiply. 10% opacity brush is usually good. And also darkened the background, and maybe used a subtle vignette. But that''s what I would''ve done. Nice shot though! 8', '2013-11-25 12:31:39.000000', NULL, 1),
(7134748, 1092764, 100773, '<td valign="top">There''s more blue on the right than the left and at the top, which messes up the composition for me. Also when shooting lenses like that lighting is crucial. I''m not a 100% sure, but I think the family of angle is something you should look into. Basically it sais that when you have your camera like now, the light should be symmetrically placed to the camera on the opposite side, kinda. Kinda like a crocodile mouth. Anyway, that would make the lens look more like a product shot. I also think all the text should be sharp.</td>', 'There''s more blue on the right than the left and at the top, which messes up the composition for me. Also when shooting lenses like that lighting is crucial. I''m not a 100% sure, but I think the family of angle is something you should look into. Basically it sais that when you have your camera like now, the light should be symmetrically placed to the camera on the opposite side, kinda. Kinda like a crocodile mouth. Anyway, that would make the lens look more like a product shot. I also think all the text should be sharp.', '2013-11-25 12:38:28.000000', NULL, 1),
(7134749, 1091975, 100773, '<td valign="top">Bad title on a nice photo. 7</td>', 'Bad title on a nice photo. 7', '2013-11-25 12:38:48.000000', NULL, 1),
(7134750, 1091897, 100773, '<td valign="top">Had you googled "how to photograph glass" you would''ve found a solution that would make this shot look more professional. I don''t like the way you have shot this. Sorry.</td>', 'Had you googled "how to photograph glass" you would''ve found a solution that would make this shot look more professional. I don''t like the way you have shot this. Sorry.', '2013-11-25 12:40:26.000000', NULL, 1),
(7134751, 1092380, 100773, '<td valign="top">I hope you fare well with this abstraction. I like it a lot. 8</td>', 'I hope you fare well with this abstraction. I like it a lot. 8', '2013-11-25 12:40:56.000000', NULL, 1),
(7134756, 1092557, 100773, '<td valign="top">I think this composition is to challenging. You''ve cropped both the bottle and glass, and positioned them the way you have done makes this feel incomplete to me. Sorry. 4</td>', 'I think this composition is to challenging. You''ve cropped both the bottle and glass, and positioned them the way you have done makes this feel incomplete to me. Sorry. 4', '2013-11-25 12:43:33.000000', NULL, 1),
(7134757, 1092650, 100773, '<td valign="top">I don''t think you need the top of the bottles, but this is nicely done indeed. It has an intellectual feeling to it. 8</td>', 'I don''t think you need the top of the bottles, but this is nicely done indeed. It has an intellectual feeling to it. 8', '2013-11-25 12:44:19.000000', NULL, 1),
(7134758, 1092329, 100773, '<td valign="top">I would be a bit more carefull with the reflections in such a shot. You play with abstraction here, and the reflections tones down the brilliance of it. 6</td>', 'I would be a bit more carefull with the reflections in such a shot. You play with abstraction here, and the reflections tones down the brilliance of it. 6', '2013-11-25 12:45:23.000000', NULL, 1),
(7134759, 1092730, 100773, '<td valign="top">The bottle and the standing glass is nicely lit, but the glass up in the air there kinda ruins it since it doesn''t have the same reflections. I would''ve framed it tighter with a more shallow dof and pushed the bottle further back I think.7</td>', 'The bottle and the standing glass is nicely lit, but the glass up in the air there kinda ruins it since it doesn''t have the same reflections. I would''ve framed it tighter with a more shallow dof and pushed the bottle further back I think.7', '2013-11-25 12:50:04.000000', NULL, 1),
(7134776, 1092653, 22384, '<td valign="top">Love the equivocating in the concept and the title. Creative and fun. Interesting composition. It is like I am being observed as the observer.</td>', 'Love the equivocating in the concept and the title. Creative and fun. Interesting composition. It is like I am being observed as the observer.', '2013-11-25 14:22:50.000000', NULL, 1),
(7134777, 1091916, 22384, '<td valign="top">No matter what the challenge, stunning picture! This could be in National Geographic. Stellar in every way! 10</td>', 'No matter what the challenge, stunning picture! This could be in National Geographic. Stellar in every way! 10', '2013-11-25 14:24:07.000000', NULL, 1),
(7134778, 1092811, 22384, '<td valign="top">You certainly met the challenge. The motif of triangles moving to the peak draw the viewer''s eye up, almost violently. This would be a great image in an ad with the text above it. Stunning lines.</td>', 'You certainly met the challenge. The motif of triangles moving to the peak draw the viewer''s eye up, almost violently. This would be a great image in an ad with the text above it. Stunning lines.', '2013-11-25 14:26:15.000000', NULL, 1),
(7134779, 1092830, 22384, '<td valign="top">So Creative. I haven''t a clue how you did this, but it is stunning! I love that you left all the elements of the light bulb (if that is what it is)and the reversed text. Well done!</td>', 'So Creative. I haven''t a clue how you did this, but it is stunning! I love that you left all the elements of the light bulb (if that is what it is)and the reversed text. Well done!', '2013-11-25 14:28:09.000000', NULL, 1),
(7134780, 1092672, 22384, '<td valign="top">Interesting composition. Nice contrast of textures and use of the value scale.</td>', 'Interesting composition. Nice contrast of textures and use of the value scale.', '2013-11-25 14:29:53.000000', NULL, 1),
(7134781, 1092483, 22384, '<td valign="top">Creative idea, and I love your focal point.</td>', 'Creative idea, and I love your focal point.', '2013-11-25 14:30:58.000000', NULL, 1),
(7134782, 1092550, 22384, '<td valign="top">So surreal and trippy! It reminds me of Johnny Depp in Sleepy Hollow. I would have liked her magnified hair to be clearer instead of smudged. Still, nice shot.</td>', 'So surreal and trippy! It reminds me of Johnny Depp in Sleepy Hollow. I would have liked her magnified hair to be clearer instead of smudged. Still, nice shot.', '2013-11-25 14:33:06.000000', NULL, 1),
(7134783, 1092814, 22384, '<td valign="top">Nice shot and great idea! I would have cropped it closer and moved your focal point closer to the crosshairs at the edge of the lower left section.</td>', 'Nice shot and great idea! I would have cropped it closer and moved your focal point closer to the crosshairs at the edge of the lower left section.', '2013-11-25 14:35:39.000000', NULL, 1),
(7134786, 1092570, 22384, '<td valign="top">Well, heck! I am an English teacher who writes horror. How am I not going to love this? The skull facing to the left (past) on a copy of Shakespeare''s works, with a cracked spine, no less. (Alas, poor Yorick...) The beautifully matched motif of hatched lines on the glass and the bottle. The neck of the wine bottle out of frame. With all that going on and my eye is still drawn to the wine glass as the perfect focal point for this challenge. I would hang this on my wall. IMHO, Stunning Shot! 10</td>', 'Well, heck! I am an English teacher who writes horror. How am I not going to love this? The skull facing to the left (past) on a copy of Shakespeare''s works, with a cracked spine, no less. (Alas, poor Yorick...) The beautifully matched motif of hatched lines on the glass and the bottle. The neck of the wine bottle out of frame. With all that going on and my eye is still drawn to the wine glass as the perfect focal point for this challenge. I would hang this on my wall. IMHO, Stunning Shot! 10', '2013-11-25 14:42:29.000000', NULL, 1),
(7134787, 1092703, 22384, '<td valign="top">Interesting piece. I like that you chose to go monochromatic with only this piece. Well done!</td>', 'Interesting piece. I like that you chose to go monochromatic with only this piece. Well done!', '2013-11-25 14:44:26.000000', NULL, 1),
(7134788, 1092720, 22384, '<td valign="top">I don''t see sparkling, but then I am sure you were being ironic with the title. I also don''t see much glass. The leaf takes up too much of the frame. Let me see some reflection or refraction or sparkle. All the things that glass is know for and makes it so difficult to shoot. You went too safe with this for my tastes.</td>', 'I don''t see sparkling, but then I am sure you were being ironic with the title. I also don''t see much glass. The leaf takes up too much of the frame. Let me see some reflection or refraction or sparkle. All the things that glass is know for and makes it so difficult to shoot. You went too safe with this for my tastes.', '2013-11-25 14:47:37.000000', NULL, 1),
(7134789, 1092151, 22384, '<td valign="top">This is creative, I''ll give you that. But, I really do want to see glass in a glass challenge.</td>', 'This is creative, I''ll give you that. But, I really do want to see glass in a glass challenge.', '2013-11-25 14:48:26.000000', NULL, 1),
(7134790, 1092798, 22384, '<td valign="top">Interesting lighting, but I think it blows out the glass too much. It messes with the clean lines that would have been a beautiful contrast to the soft glow surrounding the hand. Brilliant idea, though.</td>', 'Interesting lighting, but I think it blows out the glass too much. It messes with the clean lines that would have been a beautiful contrast to the soft glow surrounding the hand. Brilliant idea, though.', '2013-11-25 14:50:37.000000', NULL, 1),
(7134793, 1092723, 22384, '<td valign="top">Interesting use of framing. The angle is a little to extreme for me (too much of the inside of the backside of the glass shade is showing, IMHO). I do like the flower at the bottom middle that draws my eye. the background doesn''t work for me with this piece. I might have flipped the curves and gone totally black or totally white, not sure; I would have had to seen the results before choosing.</td>', 'Interesting use of framing. The angle is a little to extreme for me (too much of the inside of the backside of the glass shade is showing, IMHO). I do like the flower at the bottom middle that draws my eye. the background doesn''t work for me with this piece. I might have flipped the curves and gone totally black or totally white, not sure; I would have had to seen the results before choosing.', '2013-11-25 14:55:06.000000', NULL, 1),
(7134796, 1092717, 22384, '<td valign="top">I like this piece, and I love the background. The crooked double shot "glass" is supposed to add interest (I think), but it is distracting to me. It takes away from the vivid blue lid that makes the background work so well.</td>', 'I like this piece, and I love the background. The crooked double shot "glass" is supposed to add interest (I think), but it is distracting to me. It takes away from the vivid blue lid that makes the background work so well.', '2013-11-25 14:58:03.000000', NULL, 1),
(7134797, 1092832, 22384, '<td valign="top">I love blown out images and the complete use of the value scale. The composition is nice, but the fuzziness of the "splotches" around the outside edges make it look too blown out even for my tastes. I would have cleaned those up, or probably gotten rid of them completely. It is an advanced editing challenge, so I say get those out of there.</td>', 'I love blown out images and the complete use of the value scale. The composition is nice, but the fuzziness of the "splotches" around the outside edges make it look too blown out even for my tastes. I would have cleaned those up, or probably gotten rid of them completely. It is an advanced editing challenge, so I say get those out of there.', '2013-11-25 15:02:32.000000', NULL, 1),
(7134798, 1092256, 22384, '<td valign="top">This looks like a blown out image of a car to me. I am not sure that it meets the challenge.</td>', 'This looks like a blown out image of a car to me. I am not sure that it meets the challenge.', '2013-11-25 15:03:34.000000', NULL, 1),
(7134800, 1092808, 22384, '<td valign="top">I seriously always wondered what the "rye" from the song "American Pie" was exactly, but I was just too lazy to look it up. I mean, I knew it was some type of alcohol, but now I not only know but have an image to refer to. Interesting shot. I love the reflections and the top of the the glass. I also like the composition of the top of the bottle being out of frame, and the bottle top placed just so barely in the foreground to create the perfect perspective. Love the lighting. Well done!</td>', 'I seriously always wondered what the "rye" from the song "American Pie" was exactly, but I was just too lazy to look it up. I mean, I knew it was some type of alcohol, but now I not only know but have an image to refer to. Interesting shot. I love the reflections and the top of the the glass. I also like the composition of the top of the bottle being out of frame, and the bottle top placed just so barely in the foreground to create the perfect perspective. Love the lighting. Well done!', '2013-11-25 15:11:04.000000', NULL, 1),
(7134801, 1092816, 22384, '<td valign="top">Creative and interesting, but just too busy for me. It makes me dizzy to look at it. Given your title, that is what you were going for, so you certainly achieved your goal. :)</td>', 'Creative and interesting, but just too busy for me. It makes me dizzy to look at it. Given your title, that is what you were going for, so you certainly achieved your goal. :)', '2013-11-25 15:13:36.000000', NULL, 1),
(7134807, 1092231, 22384, '<td valign="top">You captured so much in this image. I love the red and wood grain, which matches the flora outside the window, combined stunningly with the blue water and sky reflecting off the tops of the tables. But it is the man at the far left of the image who really makes it work. Dang, even his shirt works with the composition so he doesn''t distract, but adds to the image. So well done! It almost captures an era.</td>', 'You captured so much in this image. I love the red and wood grain, which matches the flora outside the window, combined stunningly with the blue water and sky reflecting off the tops of the tables. But it is the man at the far left of the image who really makes it work. Dang, even his shirt works with the composition so he doesn''t distract, but adds to the image. So well done! It almost captures an era.', '2013-11-25 15:27:03.000000', NULL, 1),
(7134808, 1092316, 22384, '<td valign="top">Your title nails it. Intense image!</td>', 'Your title nails it. Intense image!', '2013-11-25 15:27:47.000000', NULL, 1),
(7134809, 1092329, 22384, '<td valign="top">Great color and lines. I am sure it was your intention to have the bottle top reflected in the glass on the right, but that is a distraction for me. I also would have cleaned up the reflections in the stem of the glass on the left. They distract from an otherwise stunning piece.</td>', 'Great color and lines. I am sure it was your intention to have the bottle top reflected in the glass on the right, but that is a distraction for me. I also would have cleaned up the reflections in the stem of the glass on the left. They distract from an otherwise stunning piece.', '2013-11-25 15:30:07.000000', NULL, 1),
(7134810, 1092614, 22384, '<td valign="top">Haunting and creative image and title.</td>', 'Haunting and creative image and title.', '2013-11-25 15:30:54.000000', NULL, 1),
(7134812, 1092685, 22384, '<td valign="top">So clean and perfect. Nice lines. It looks like an ad in a magazine. So clean and well lit. Great color choice. Brilliant shot.</td>', 'So clean and perfect. Nice lines. It looks like an ad in a magazine. So clean and well lit. Great color choice. Brilliant shot.', '2013-11-25 15:32:13.000000', NULL, 1),
(7134813, 1092727, 22384, '<td valign="top">I am not quite sure what you were going for, but there is interesting movement in this shot.</td>', 'I am not quite sure what you were going for, but there is interesting movement in this shot.', '2013-11-25 15:33:40.000000', NULL, 1),
(7134814, 1092307, 22384, '<td valign="top">Beautiful desat great color accents. Wonderful composition and the cracks make it perfect. I am not sure if that is ice or glass, but I don''t care; I like it a lot.</td>', 'Beautiful desat great color accents. Wonderful composition and the cracks make it perfect. I am not sure if that is ice or glass, but I don''t care; I like it a lot.', '2013-11-25 15:36:06.000000', NULL, 1),
(7134815, 1092742, 22384, '<td valign="top">The blue against the black background is captivating.</td>', 'The blue against the black background is captivating.', '2013-11-25 15:36:48.000000', NULL, 1),
(7134816, 1091897, 22384, '<td valign="top">Nice composition, but the yellow light reflections are distracting. I would have edited them out.</td>', 'Nice composition, but the yellow light reflections are distracting. I would have edited them out.', '2013-11-25 15:37:49.000000', NULL, 1),
(7134818, 1092621, 22384, '<td valign="top">So clever! I love the idea. Since it is advanced editing, I would have straightened the lines refracted through some of the glasses, especially the one on the far left. Then it would have been the perfect shot!</td>', 'So clever! I love the idea. Since it is advanced editing, I would have straightened the lines refracted through some of the glasses, especially the one on the far left. Then it would have been the perfect shot!', '2013-11-25 15:39:31.000000', NULL, 1),
(7134820, 1092537, 22384, '<td valign="top">The lights that are on in the windows give this shot a nice touch. If it weren''t for that, I would have to say I''ve seen this over and over...</td>', 'The lights that are on in the windows give this shot a nice touch. If it weren''t for that, I would have to say I''ve seen this over and over...', '2013-11-25 15:41:06.000000', NULL, 1),
(7134821, 1092536, 22384, '<td valign="top">I like the movement down and out of the frame. I wish that you would have done something with the background, color, pure white, white with burned edges... It is just lacking something...</td>', 'I like the movement down and out of the frame. I wish that you would have done something with the background, color, pure white, white with burned edges... It is just lacking something...', '2013-11-25 15:43:16.000000', NULL, 1),
(7134822, 1092380, 22384, '<td valign="top">This looks like a Monet...beautiful. Was that your intention? Did you do it with editing or were you able to achieve this without editing? Either way, it is a stunning piece. I love it! 10</td>', 'This looks like a Monet...beautiful. Was that your intention? Did you do it with editing or were you able to achieve this without editing? Either way, it is a stunning piece. I love it! 10', '2013-11-25 15:45:39.000000', NULL, 1),
(7134831, 1092385, 22384, '<td valign="top">Nice job of the reflection in the lens. Beautiful composition.</td>', 'Nice job of the reflection in the lens. Beautiful composition.', '2013-11-25 16:32:03.000000', NULL, 1),
(7134832, 1092642, 22384, '<td valign="top">Nice capture. I love the reflection in the side mirror and how perfect a couple of the drops of rain are. I also like the sense of a picture within a picture. Great idea. Well done.</td>', 'Nice capture. I love the reflection in the side mirror and how perfect a couple of the drops of rain are. I also like the sense of a picture within a picture. Great idea. Well done.', '2013-11-25 16:34:19.000000', NULL, 1),
(7134834, 1092574, 22384, '<td valign="top">Crisp and stunning. Looks ready for an ad in Maxim, G.Q. etc... There is only that one "too" bright reflected spot in the reflection of the bottle. Other than that, it''s truly stellar!</td>', 'Crisp and stunning. Looks ready for an ad in Maxim, G.Q. etc... There is only that one "too" bright reflected spot in the reflection of the bottle. Other than that, it''s truly stellar!', '2013-11-25 16:39:54.000000', NULL, 1),
(7134835, 1092835, 22384, '<td valign="top">Looks like an E.C. Escher drawing. I love it. Stunning! 10</td>', 'Looks like an E.C. Escher drawing. I love it. Stunning! 10', '2013-11-25 16:40:58.000000', NULL, 1),
(7134838, 1092596, 22384, '<td valign="top">Nice movement in this shot. It certainly draws my eye down and out of the frame.</td>', 'Nice movement in this shot. It certainly draws my eye down and out of the frame.', '2013-11-25 16:45:40.000000', NULL, 1),
(7134839, 1091975, 22384, '<td valign="top">I think I would have liked this shot better without the flowers. Maybe something more subtle in the foreground to let the stunning background shine.</td>', 'I think I would have liked this shot better without the flowers. Maybe something more subtle in the foreground to let the stunning background shine.', '2013-11-25 16:47:00.000000', NULL, 1),
(7134840, 1092807, 22384, '<td valign="top">Beautiful lighting and use of the value scale. The mouth of the bottle and the lettering are especially stunning. 9</td>', 'Beautiful lighting and use of the value scale. The mouth of the bottle and the lettering are especially stunning. 9', '2013-11-25 16:48:56.000000', NULL, 1),
(7134841, 1092338, 22384, '<td valign="top">The soft image in the foreground takes up too much of the frame. I think I would have cropped in about 20% on the right side. I do like the reflection in the mirror concept.</td>', 'The soft image in the foreground takes up too much of the frame. I think I would have cropped in about 20% on the right side. I do like the reflection in the mirror concept.', '2013-11-25 16:50:59.000000', NULL, 1),
(7134842, 1092554, 22384, '<td valign="top">This concept is captivating. Nice lighting. I would have completely flipped the curves in the background to lose the line, or edited it out another way; it distracts me, but that is just my personal taste. I love the variety of flow in the color. It creates a soft sense of movement in this piece. 8</td>', 'This concept is captivating. Nice lighting. I would have completely flipped the curves in the background to lose the line, or edited it out another way; it distracts me, but that is just my personal taste. I love the variety of flow in the color. It creates a soft sense of movement in this piece. 8', '2013-11-25 16:53:49.000000', NULL, 1),
(7134843, 1092763, 22384, '<td valign="top">Nice reflections in the glass, but I feel like I have seen this image over and over and over.</td>', 'Nice reflections in the glass, but I feel like I have seen this image over and over and over.', '2013-11-25 16:54:35.000000', NULL, 1),
(7134844, 1092730, 22384, '<td valign="top">I have no idea how you did this, but stunning. This is so picky, but I want that packaging seam edited out or turned on the bottle to the back if possible. Other than that, beautiful composition, lighting, and color choices. 9</td>', 'I have no idea how you did this, but stunning. This is so picky, but I want that packaging seam edited out or turned on the bottle to the back if possible. Other than that, beautiful composition, lighting, and color choices. 9', '2013-11-25 16:58:11.000000', NULL, 1),
(7134845, 1092650, 22384, '<td valign="top">Fun idea. Love the opposite reflections in the g//www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1092650#lasses. Very creative! 8</td>', 'Fun idea. Love the opposite reflections in the g//www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1092650#lasses. Very creative! 8', '2013-11-25 16:59:23.000000', NULL, 1),
(7134846, 1092664, 22384, '<td valign="top">Fun angle,interesting lighting, and the pictures in the background work well for me.</td>', 'Fun angle,interesting lighting, and the pictures in the background work well for me.', '2013-11-25 17:00:09.000000', NULL, 1),
(7134847, 1092713, 22384, '<td valign="top">I absolutely love the blown bulb in the flash, but I think the image would have been better without the new bulbs in the foreground. That blown bulb could easily stand alone.</td>', 'I absolutely love the blown bulb in the flash, but I think the image would have been better without the new bulbs in the foreground. That blown bulb could easily stand alone.', '2013-11-25 17:01:48.000000', NULL, 1),
(7134848, 1092737, 22384, '<td valign="top">Stunning use of color and reflection.</td>', 'Stunning use of color and reflection.', '2013-11-25 17:02:16.000000', NULL, 1),
(7134849, 1092656, 22384, '<td valign="top">Oh, how we all hate the look of that. It certainly evokes emotion in me. Every time I drop my phone...yikes. Nice capture. I am not sure what the symbolism is of the image in the background. I can imagine a few things...none of them good. Nice use of composition and lighting. Well done.</td>', 'Oh, how we all hate the look of that. It certainly evokes emotion in me. Every time I drop my phone...yikes. Nice capture. I am not sure what the symbolism is of the image in the background. I can imagine a few things...none of them good. Nice use of composition and lighting. Well done.', '2013-11-25 17:04:35.000000', NULL, 1),
(7134852, 1092833, 22384, '<td valign="top">Another image that reminds me of E.C. Escher. This is picky and a bit unfair, but her nail polish is driving me crazy. Beautiful model. Excellent idea!</td>', 'Another image that reminds me of E.C. Escher. This is picky and a bit unfair, but her nail polish is driving me crazy. Beautiful model. Excellent idea!', '2013-11-25 17:06:24.000000', NULL, 1),
